package gadomancymodern.test;
import gadomancymodern.aura.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraftforge.gametest.*;
/** Loaded-mod generators: absent integrations are not counted as passes. */
@GameTestHolder("gadomancy") @PrefixGameTestTemplate(false)
public class AuraOptionalCompatServerTests {
    @GameTestGenerator public static java.util.Collection<TestFunction> installed(){var tests=new java.util.ArrayList<TestFunction>();var mods=net.minecraftforge.fml.ModList.get();if(mods.isLoaded("automagy"))tests.add(new TestFunction("gad_optional","gadomancy.automagy_actual_workbench_aura_cooling","gadomancy:test_empty",100,0,true,AuraOptionalCompatServerTests::workbench));if(mods.isLoaded("thaumic_tinkerer"))tests.add(new TestFunction("gad_optional","gadomancy.tinkerer_actual_infused_crop_aura_growth","gadomancy:test_empty",100,0,true,AuraOptionalCompatServerTests::crop));return tests;}
    public static void workbench(GameTestHelper test){var level=test.getLevel();var pos=test.absolutePos(new BlockPos(2,3,2));var block=net.minecraftforge.registries.ForgeRegistries.BLOCKS.getValue(ResourceLocation.parse("automagy:golem_workbench"));test.assertTrue(block!=null&&block!=net.minecraft.world.level.block.Blocks.AIR,"Actual Automagy workbench registered");level.setBlockAndUpdate(pos,block.defaultBlockState());var tile=level.getBlockEntity(pos);var tag=tile.saveWithoutMetadata();tag.putInt("Heat",1800);tile.load(tag);AuraEffectRegistry.effects().get("fabrico").block(level,pos,pos);test.assertTrue(tile.saveWithoutMetadata().getInt("Heat")==1100,"Fabrico lowers real overheated workbench by original 700 heat");AuraCompat.coolWorkbench(level,pos);test.assertTrue(tile.saveWithoutMetadata().getInt("Heat")==1100,"Already cool workbench not overcooled");level.removeBlock(pos,false);test.succeed();}
    public static void crop(GameTestHelper test){var level=test.getLevel();var pos=test.absolutePos(new BlockPos(2,30,2));var block=net.minecraftforge.registries.ForgeRegistries.BLOCKS.getValue(ResourceLocation.parse("thaumic_tinkerer:infused_crop"));test.assertTrue(block!=null&&block!=net.minecraft.world.level.block.Blocks.AIR,"Actual Tinkerer crop registered");level.setBlockAndUpdate(pos.below(),net.minecraft.world.level.block.Blocks.FARMLAND.defaultBlockState());level.setBlockAndUpdate(pos,block.defaultBlockState());level.setBlockAndUpdate(pos.above(2),net.minecraft.world.level.block.Blocks.GLOWSTONE.defaultBlockState());var tile=level.getBlockEntity(pos);var tag=tile.saveWithoutMetadata();var genes=new net.minecraft.nbt.CompoundTag();genes.putInt("aqua",50);tag.put("Traits",genes);tile.load(tag);var age=(net.minecraft.world.level.block.state.properties.IntegerProperty)block.getStateDefinition().getProperty("age");test.succeedWhen(()->{test.assertTrue(level.getRawBrightness(pos.above(),0)>=9,"Block light reaches crop before growth attempts");for(int i=0;i<200&&level.getBlockState(pos).getValue(age)<7;i++)AuraCompat.growCrop(level,pos);test.assertTrue(level.getBlockState(pos).getValue(age)==7,"Optional herba hook advances actual crop ticks to maturity");level.removeBlock(pos,false);});}
}
